  let currentCount = bot.inventory.count(mcData.itemsByName["oak_log"].id);
  let toMine = needed - currentCount;
  if (toMine <= 0) {
    _govSafeChat(bot, "Already have enough oak logs.");
    return;
  }
  const directions = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1), new Vec3(1, 0, 1), new Vec3(-1, 0, -1), new Vec3(1, 0, -1), new Vec3(-1, 0, 1)];
  while (toMine > 0) {if (globalThis.__govActive !== "gov_log_0") return;
    const dir = directions[Math.floor(Math.random() * directions.length)];
