        matching: block => block.name === "oak_log",
        maxDistance: 32
      });
    });if (globalThis.__govActive !== "gov_log_0") return;
    if (!oakLog) {
      _govSafeChat(bot, "Could not find any oak logs nearby.");
      break;
    }
